1	"use server";
2	/**
3	 * Work-order server actions (Phase 3 — fully wired).
4	 *
5	 * Per PRODUCTION-PLAN §7.4. State machine (enforced in code via TRANSITIONS):
6	 *   open → quoted → accepted → in_progress → delivered → closed
7	 *     └──────┴──────────┴───────────┴────────────┴──→ cancelled
8	 * `closed` and `cancelled` are terminal. `cancelled` is reachable from any
9	 * non-terminal state. Both `quoteWorkOrder` and `updateWorkOrderStatus`
10	 * read current status first and reject illegal transitions.
11	 *
12	 * Notifications go through `lib/resend.ts` + `lib/resend-templates.ts`. Every
13	 * email send is wrapped so a Resend / DKIM failure cannot break the underlying
14	 * action (work order still progresses).
15	 *
16	 * Invoice model (LOCKED): accepting a quote ONLY flips the work order to
17	 * `accepted` (+ `accepted_at`). The Stripe invoice is created later by the
18	 * ADMIN via the "Create Stripe Invoice" button (→ `createInvoiceForWorkOrder`
19	 * in lib/actions/invoices.ts). There is intentionally no auto-invoice on
20	 * accept — `work_orders.project_id` was never set client-side, so that branch
21	 * was dead anyway.
22	 *
23	 * Attachment uploads are a two-step signed-URL flow:
24	 *   1. `submitWorkOrder` validates size + MIME, inserts the work order, and
25	 *      mints a signed upload URL per attachment (no row inserted yet).
26	 *   2. The client PUTs the bytes, then calls `finalizeWorkOrderAttachment`
27	 *      which inserts the `work_order_attachments` row pointing at the real
28	 *      object. Row-after-bytes means a failed PUT never leaves a dangling
29	 *      attachment row whose signed-download link 404s.
30	 */
31	import { revalidatePath } from "next/cache";
32	import { z } from "zod";
33	import { requireUser, requireAdmin, AuthError } from "@/lib/actions/auth";
34	import type { WorkOrderStatus } from "@/lib/database.types";
35	import { sendEmail } from "@/lib/resend";
36	import {
37	  workOrderReceivedToAdmin,
38	  workOrderQuoteSentToClient,
39	  workOrderAcceptedToAdmin,
40	  workOrderStatusChangedToClient
41	} from "@/lib/resend-templates";
42	import { cioTrack, isCustomerIoConfigured } from "@/lib/customerio";
43	import { createAdminClient } from "@/lib/supabase/server";
44	
45	/**
46	 * Allowed work-order status transitions. `closed`/`cancelled` are terminal
47	 * (empty arrays). `cancelled` is reachable from every non-terminal state.
48	 */
49	const TRANSITIONS: Record<WorkOrderStatus, readonly WorkOrderStatus[]> = {
50	  open: ["quoted", "cancelled"],
51	  quoted: ["accepted", "cancelled"],
52	  accepted: ["in_progress", "cancelled"],
53	  in_progress: ["delivered", "cancelled"],
54	  delivered: ["closed", "cancelled"],
55	  closed: [],
56	  cancelled: []
57	};
58	
59	function canTransition(from: WorkOrderStatus, to: WorkOrderStatus): boolean {
60	  return TRANSITIONS[from]?.includes(to) ?? false;
61	}
62	
63	const MAX_FILE_SIZE_BYTES = 25 * 1024 * 1024;
64	
65	const ALLOWED_MIME = new Set<string>([
66	  "image/png",
67	  "image/jpeg",
68	  "image/webp",
69	  "image/gif",
70	  "image/svg+xml",
71	  "application/pdf",
72	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
73	  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
74	  "application/vnd.openxmlformats-officedocument.presentationml.presentation",
75	  "text/plain",
76	  "text/csv"
77	]);
78	
79	const uuid = z.string().uuid("invalid id");
80	const positiveInt = z
81	  .number()
82	  .int("must be an integer")
83	  .positive("must be > 0")
84	  .max(1_000_000_000, "absurdly large");
85	
86	const submitInput = z.object({
87	  service_type: z.enum(["logo", "website_update", "data_export", "consulting", "other"]),
88	  title: z.string().trim().min(2, "title too short").max(160, "title too long"),
89	  description: z.string().trim().max(8000).optional().nullable(),
90	  attachments: z
91	    .array(
92	      z.object({
93	        filename: z.string().min(1).max(255),
94	        mime_type: z.string().min(1).max(127),
95	        size_bytes: z.number().int().nonnegative()
96	      })
97	    )
98	    .max(8, "too many attachments")
99	    .optional()
100	});
101	
102	export type SubmitWorkOrderInput = z.infer<typeof submitInput>;
103	
104	export type ActionResult<T> = { ok: true; data: T } | { ok: false; error: string };
105	
106	const ADMIN_NOTIFY_TO = (): string =>
107	  process.env.RESEND_REPLY_TO ?? "jeremyw@dobeu.net";
108	
109	/** One signed upload target the client PUTs bytes to, then finalizes. */
110	export interface UploadTarget {
111	  storage_path: string;
112	  token: string;
113	  filename: string;
114	  mime_type: string;
115	  size_bytes: number;
116	}
117	
118	export async function submitWorkOrder(
119	  raw: unknown
120	): Promise<ActionResult<{ id: string; uploadPaths: string[]; uploadTargets: UploadTarget[] }>> {
121	  const parsed = submitInput.safeParse(raw);
122	  if (!parsed.success) {
123	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
124	  }
125	  const input = parsed.data;
126	
127	  for (const att of input.attachments ?? []) {
128	    if (att.size_bytes > MAX_FILE_SIZE_BYTES) {
129	      return { ok: false, error: `attachment "${att.filename}" exceeds 25 MB cap` };
130	    }
131	    if (!ALLOWED_MIME.has(att.mime_type)) {
132	      return { ok: false, error: `attachment "${att.filename}" mime ${att.mime_type} not allowed` };
133	    }
134	  }
135	
136	  let user, supabase;
137	  try {
138	    ({ user, supabase } = await requireUser());
139	  } catch (e) {
140	    if (e instanceof AuthError) return { ok: false, error: e.code };
141	    throw e;
142	  }
143	
144	  const { data: inserted, error: insertErr } = await supabase
145	    .from("work_orders")
146	    .insert({
147	      created_by: user.id,
148	      service_type: input.service_type,
149	      title: input.title,
150	      description: input.description ?? null,
151	      status: "open"
152	    })
153	    .select("id")
154	    .single();
155	
156	  if (insertErr || !inserted) {
157	    return { ok: false, error: insertErr?.message ?? "insert failed" };
158	  }
159	
160	  const workOrderId = inserted.id;
161	  const uploadPaths: string[] = [];
162	  const uploadTargets: UploadTarget[] = [];
163	
164	  // Mint a signed upload URL per attachment using the SERVICE-ROLE client.
165	  // Ownership is already established (requireUser + the WO insert above) and
166	  // the signed token itself authorizes the client's subsequent PUT — minting
167	  // via admin sidesteps any sign-time RLS evaluation of the storage INSERT
168	  // policy, so a freshly-created WO can never fail to mint for a policy reason.
169	  // The path is `<work_order_id>/...` which also satisfies that policy at PUT
170	  // time. NO attachment row is inserted here — the client PUTs the bytes, then
171	  // calls `finalizeWorkOrderAttachment` (cookie-bound, RLS-enforced) to insert
172	  // the row. Row-after-bytes keeps signed-download links from 404ing.
173	  const storageAdmin = createAdminClient();
174	  for (const att of input.attachments ?? []) {
175	    const storagePath = `${workOrderId}/${crypto.randomUUID()}-${att.filename}`;
176	    const { data: signed, error: signErr } = await storageAdmin.storage
177	      .from("work-order-attachments")
178	      .createSignedUploadUrl(storagePath);
179	    if (signErr || !signed) {
180	      console.warn(
181	        "[submitWorkOrder] signed upload URL failed for",
182	        att.filename,
183	        signErr?.message
184	      );
185	      continue;
186	    }
187	    uploadPaths.push(storagePath);
188	    uploadTargets.push({
189	      storage_path: storagePath,
190	      [REDACTED],
191	      filename: att.filename,
192	      mime_type: att.mime_type,
193	      size_bytes: att.size_bytes
194	    });
195	  }
196	
197	  const profileEmail = user.email ?? "(no email)";
198	  const profileName =
199	    (user.user_metadata as { full_name?: string } | null)?.full_name ?? null;
200	
201	  // Resend admin notification (non-fatal).
202	  try {
203	    const tpl = workOrderReceivedToAdmin({
204	      workOrder: {
205	        id: workOrderId,
206	        title: input.title,
207	        service_type: input.service_type,
208	        description: input.description ?? null
209	      },
210	      client: { email: profileEmail, name: profileName }
211	    });
212	    await sendEmail({
213	      to: ADMIN_NOTIFY_TO(),
214	      subject: tpl.subject,
215	      text: tpl.text,
216	      html: tpl.html
217	    });
218	  } catch (e) {
219	    console.warn("[submitWorkOrder] admin notify failed (non-fatal):", e);
220	  }
221	
222	  // Emit a best-effort `work_order_created` event (non-fatal — mirrors
223	  // processLead's discipline; a failure here must never drop the work order).
224	  //
225	  // NOTE: there is no server-side Intercom event helper in this codebase
226	  // (lib/intercom.ts is the client-side Messenger SDK only). Customer.io is
227	  // the established server-side event channel (lib/customerio.ts, used by the
228	  // lead pipeline), so the event lands there. If/when a server Intercom event
229	  // API is added, point this at it instead.
230	  try {
231	    if (user.email && isCustomerIoConfigured()) {
232	      const res = await cioTrack({
233	        email: user.email,
234	        name: "work_order_created",
235	        data: {
236	          work_order_id: workOrderId,
237	          title: input.title,
238	          service_type: input.service_type
239	        }
240	      });
241	      if (!res.ok) {
242	        console.warn("[submitWorkOrder] work_order_created event failed (non-fatal):", res.error);
243	      }
244	    }
245	  } catch (e) {
246	    console.warn("[submitWorkOrder] work_order_created event threw (non-fatal):", e);
247	  }
