249	  revalidatePath("/portal");
250	  revalidatePath("/portal/tickets");
251	  revalidatePath("/admin");
252	  revalidatePath("/admin/tickets");
253	  return { ok: true, data: { id: workOrderId, uploadPaths, uploadTargets } };
