            <LayoutDashboard className="h-4 w-4" aria-hidden="true" /> <span className="hidden sm:inline">Portal view</span>
          </Link>
          <LogoutButton />
        </nav>
      </aside>
      <div className="flex-1 min-w-0">
        <main className="p-4 md:p-8 max-w-6xl">{children}</main>
      </div>
    </div>
  );
}

